#include <queue>
#include <cassert>
#include <iostream>

int main() {
    std::queue<int> values;
    values.push(2);
    values.push(7);
    assert(values.front() == 2);
    assert(values.back() == 7);
    std::queue<int> copy;
    copy = values;
    assert(copy == values);
    values.pop();
    assert(values.front() == 7);
    std::cout << "Checks passed\n";
}
